[CmdletBinding()]param([string]$ProjectRoot=".",[ValidateSet("general","protocol_freeze","analytical_validation","empirical_validation")][string]$StageProfile="general",[string[]]$ProtectedPathPatterns=@("src/**/analytics/**","src/**/analysis/**","src/**/hrv/**","src/**/qrs/**","src/**/ecg/**"),[switch]$AlgorithmRepairAuthorized,[string[]]$AlgorithmRepairFindingIds=@(),[switch]$Apply)
$ErrorActionPreference="Stop";$Root=(Resolve-Path $ProjectRoot).Path;$Wi=Get-Content (Join-Path $Root ".agy\WORK_ITEM.json") -Raw|ConvertFrom-Json;$Head=(& git -C $Root rev-parse HEAD).Trim();$F=[ordered]@{schema_version="1.0.0";work_item_id=[string]$Wi.work_item_id;stage_profile=$StageProfile;status=if($StageProfile-eq"general"){"inactive"}else{"active"};protected_path_patterns=$ProtectedPathPatterns;algorithm_repair_authorized=[bool]$AlgorithmRepairAuthorized;algorithm_repair_finding_ids=$AlgorithmRepairFindingIds;analytical_baseline_head=$Head;generated_at_utc=(Get-Date).ToUniversalTime().ToString("o")};$Out=Join-Path $Root ".agy\STAGE_FIREWALL.json";if($Apply){[IO.File]::WriteAllText($Out,($F|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));Write-Host "Stage firewall published."}else{$F|ConvertTo-Json -Depth 20}
